// renderStack emits the "every stack" coverage section with real inline-SVG brand
// logos (accurate simple-icons paths) plus SVG monogram tiles for the rest.
func renderStack() template.HTML {
	var b strings.Builder
	b.WriteString(`<section id="stack" class="mx-auto max-w-6xl px-4 py-16 sm:px-6">`)
	b.WriteString(`<h2 class="font-mono text-2xl font-bold text-white"><span class="text-emerald-400">$</span> cat stack.conf</h2>`)
	b.WriteString(`<p class="mt-2 font-mono text-sm text-gray-500"># one engine, every stack - 20 shown of 200+ supported</p>`)
	b.WriteString(`<div class="mt-6 space-y-6">`)
	for _, g := range stackGroups {
		fmt.Fprint(&b, `<div class="rounded border border-white/10 bg-[#04060c] p-5">`)
		fmt.Fprintf(&b, `<div class="mb-3 flex flex-wrap items-center gap-3"><span class="font-mono text-[11px] font-bold text-gray-100">▸ %s</span><span class="text-[10px] text-gray-500">(%d of 200+ supported)</span></div>`, g.Title, len(g.Items))
		b.WriteString(`<div class="grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8 lg:grid-cols-10">`)
		for _, it := range g.Items {
			tile := renderStackTile(it)
			b.WriteString(tile)
		}
		b.WriteString(`</div></div>`)
	}
	b.WriteString(`</div>`)
	b.WriteString(`<p class="mt-6 rounded border border-white/10 bg-[#04060c] p-4 font-mono text-xs leading-relaxed text-gray-300"><span class="text-emerald-300 font-bold">[+] stack-aware engine</span> - fingerprints your exact languages, frameworks and CI/CD and checks each against the <span class="text-cyan-300">latest CVE</span>, <span class="text-cyan-300">CWE</span> and <span class="text-cyan-300">OWASP Top 10</span> mappings for that stack - so version-specific vulnerabilities in your exact tech are found, not generic noise.</p>`)
	b.WriteString(`</section>`)
	return template.HTML(b.String())
}

// renderStackTile renders one tile: a real brand SVG when Path is set, otherwise a
// styled SVG monogram (initial letters) so every tile is a genuine <svg>.
func renderStackTile(it stackItem) string {
	col := it.Color
	if col == "" {
		col = "#22d3ee"
	}
	if it.Path != "" {
		return fmt.Sprintf(`<div class="flex flex-col items-center gap-1 rounded border border-white/10 bg-ink px-2 py-2" title="%s">
  <svg viewBox="0 0 24 24" width="26" height="26" role="img" aria-label="%s"><path fill="%s" d="%s"/></svg>
  <span class="truncate font-mono text-[9px] text-gray-400">%s</span></div>`,
			it.Name, it.Name, col, it.Path, it.Name)
	}
	// SVG monogram fallback
	initial := ""
	for _, r := range it.Name {
		if r >= 'A' && r <= 'Z' {
			initial += string(r)
		}
	}
	if len(initial) < 2 {
		initial = it.Name[:2]
	}
	return fmt.Sprintf(`<div class="flex flex-col items-center gap-1 rounded border border-white/10 bg-ink px-2 py-2" title="%s">
  <svg viewBox="0 0 24 24" width="26" height="26" role="img" aria-label="%s">
    <rect width="24" height="24" rx="4" fill="%s" opacity="0.15"/>
    <text x="12" y="16" font-family="monospace" font-size="11" font-weight="bold" fill="%s" text-anchor="middle">%s</text>
  </svg>
  <span class="truncate font-mono text-[9px] text-gray-400">%s</span></div>`,
		it.Name, it.Name, col, col, initial, it.Name)
}
